import { useEffect, useRef } from 'react';

export const usePageCacheLoadingGate = (
  isPageReady: boolean,
  isCacheChecking: boolean,
  isCacheHit: boolean,
  isStaleHit: boolean,
  shouldRevalidate: boolean,
): React.MutableRefObject<boolean> => {
  const wasLoadingRef = useRef(false);

  useEffect(() => {
    if (
      !isPageReady &&
      !isCacheChecking &&
      (!isCacheHit || (isStaleHit && shouldRevalidate))
    ) {
      wasLoadingRef.current = true;
    }
  }, [isPageReady, isCacheChecking, isCacheHit, isStaleHit, shouldRevalidate]);

  return wasLoadingRef;
};
